function retestPlan(fixed, tests, changedModules) {
  const fx = new Set(fixed);
  const ch = new Set(changedModules);
  const confirmation = [];
  const regression = [];
  for (const t of tests) {
    if (t.failedWith && fx.has(t.failedWith)) confirmation.push(t.id);
    else if ((t.modules || []).some((m) => ch.has(m))) regression.push(t.id);
  }
  return { confirmation: confirmation.sort(), regression: regression.sort() };
}
